#include <iostream>

class Message {
    int m_id;
public:
    Message(int id) : m_id{id} {}

    Message(const Message& src) : m_id{src.m_id} {
        std::cout << "copy " << m_id << "\n";
    }

    int id() const { return m_id; }
};

void deliver(Message m) {
    std::cout << "deliver " << m.id() << "\n";
}

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int id;
        std::cin >> id;
        Message m{id};
        deliver(m);
    }
}

