#include <iostream>

class Widget {
    int m_id;
public:
    Widget(int id) : m_id{id} {}

    // TODO (lesson 14.14): write the copy constructor for Widget.
    // Take a const Widget& source, copy m_id, and print  copied <id>  followed
    // by a newline each time it runs, so copies are observable.

    int id() const { return m_id; }
};

void byValue(Widget w) { std::cout << "byValue " << w.id() << "\n"; }
void byRef(const Widget& w) { std::cout << "byRef " << w.id() << "\n"; }

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int id;
        std::cin >> id;
        Widget w{id};
        byRef(w);    // passes by reference — no copy
        byValue(w);  // passes by value — a copy is made
    }
}

