#include <iostream>

class Widget {
    int m_id;
public:
    Widget(int id) : m_id{id} {}

    Widget(const Widget& src) : m_id{src.m_id} {
        std::cout << "copied " << m_id << "\n";
    }

    int id() const { return m_id; }
};

void byValue(Widget w) { std::cout << "byValue " << w.id() << "\n"; }
void byRef(const Widget& w) { std::cout << "byRef " << w.id() << "\n"; }

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int id;
        std::cin >> id;
        Widget w{id};
        byRef(w);
        byValue(w);
    }
}
